# Generated by build.py from recipe.yml for recipe http-expire-a-token-mid-session. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--user', 'app:s3cret', '--control', 'http://127.0.0.1:8081', '--control-token-file', 'control-token.txt', 'oci://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh client.sh https://127.0.0.1:8080/ app:s3cret token.txt && curl -s -o NUL -w "reset: %{response_code}\n" -X POST -H "Authorization: Bearer control-token-0123456789abcdefghij" http://127.0.0.1:8081/v1/reset && sh client.sh https://127.0.0.1:8080/ app:s3cret token.txt } finally { Stop-Process $server0 }
